/* Progress 0.3 — Play your day. Private, offline-first, no external dependencies.
   Compatible with the IndexedDB database and backup structure of versions 0.1 / 0.2. */
(()=>{'use strict';
const DB='progress-private-v1', STORES=['activities','entries','overrides','meta'];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>crypto.randomUUID?.()||'p'+Date.now().toString(36)+Math.random().toString(36).slice(2);
const z=n=>String(n).padStart(2,'0'), iso=d=>`${d.getFullYear()}-${z(d.getMonth()+1)}-${z(d.getDate())}`;
const today=()=>iso(new Date()), date=s=>{let [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d,12)};
const add=(s,n)=>{let d=date(s);d.setDate(d.getDate()+n);return iso(d)};
const fmt=(s,opt={weekday:'long',day:'numeric',month:'long'})=>date(s).toLocaleDateString('de-DE',opt);
const valid=n=>typeof n==='number'&&Number.isFinite(n)&&n>=0;
const num=(n,dec=1)=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:dec}).format(n);
const PERIODS={day:'Tag',week:'Woche',month:'Monat',year:'Jahr'}, WEEK=['So','Mo','Di','Mi','Do','Fr','Sa'];
const ICONS={
 fitness:'<path d="M3 10v4m3-7v10m12-10v10m3-7v4M6 12h12"/>',
 health:'<path d="M20.8 8.5c0 4.5-8.8 10.6-8.8 10.6S3.2 13 3.2 8.5a4.6 4.6 0 0 1 8.8-1.8 4.6 4.6 0 0 1 8.8 1.8z"/>',
 learning:'<path d="M12 6c-3-2-6-2-9-1v14c3-1 6-1 9 1m0-14c3-2 6-2 9-1v14c-3-1-6-1-9 1m0-14v14"/>',
 digital:'<rect x="7" y="2.5" width="10" height="19" rx="2"/><path d="M11 18.5h2"/>',
 creative:'<path d="M8 18V5l12-2v12M8 7l12-2"/><ellipse cx="5" cy="18.5" rx="3" ry="2"/><ellipse cx="17" cy="15.5" rx="3" ry="2"/>',
 productive:'<path d="M12 2v4M12 18v4M2 12h4M18 12h4"/><circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="3"/>',
 finance:'<circle cx="12" cy="12" r="9"/><path d="M15.5 8.5C14 7 9 7 9 10s6 1 6 4-5 3-6.5 1.5M12 5.5v13"/>',
 leisure:'<path d="M8 8h8a5 5 0 0 1 4.6 3l1 5a3 3 0 0 1-5 2l-2-2h-5l-2 2a3 3 0 0 1-5-2l1-5A5 5 0 0 1 8 8zM7 12h5m-2.5-2.5v5M16 11h.01M18 13h.01"/>',
 personal:'<path d="m12 2 2.7 6.8L22 12l-7.3 3.2L12 22l-2.7-6.8L2 12l7.3-3.2z"/>',
 sleep:'<path d="M20.2 16.9A9 9 0 0 1 7.1 3.8 9 9 0 1 0 20.2 16.9z"/>',
 outdoors:'<path d="m3 19 7-14 5 9 2-4 4 9zM8 19h10"/>',
 other:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5m0 4h.01"/>'};
const CAT={fitness:'Fitness',health:'Gesundheit',learning:'Lernen',digital:'Digitales',creative:'Kreativität',productive:'Produktivität',finance:'Finanzen',leisure:'Freizeit',personal:'Persönliches',sleep:'Schlaf',outdoors:'Draußen',other:'Sonstiges'};
const UI={plus:'<path d="M12 4v16M4 12h16"/>',back:'<path d="m15 5-7 7 7 7"/>',check:'<path d="m4 12 5 5L20 6"/>',edit:'<path d="m4 16 12-12 4 4-12 12H4z"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',home:'<path d="m3 10 9-7 9 7v10H4zM9 20v-7h6v7"/>',timeline:'<rect x="3" y="4" width="18" height="17" rx="2"/><path d="M3 10h18M8 2v4M16 2v4"/>',stats:'<path d="M4 19V9M10 19V5M16 19v-8M22 19v-5"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16M8 4v4M16 10v4M10 16v4"/>',dots:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',spark:'<path d="m12 2 2.4 7.6L22 12l-7.6 2.4L12 22l-2.4-7.6L2 12l7.6-2.4z"/>'};
function icon(k,cl=''){return `<svg class="icon ${cl}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true">${ICONS[k]||UI[k]||ICONS.other}</svg>`}
let db;
const S={page:'today',day:today(),history:'month',card:0,activities:[],entries:[],overrides:[],meta:[],modal:null,entryStatus:null,ruleDraft:[],theme:'system',sound:true,colors:{save:'#168a70',level:'#a1ef45'},timeout:3,packet:null,packetBusy:false,locked:false};
const EM=new Map(),OM=new Map();let timer=0, gesture=null, audio;
const cat=a=>a.category&&CAT[a.category]?a.category:(a.kind==='build'?'personal':'digital');
function catIcon(a){if(typeof a.iconData==='string'&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(a.iconData))return `<img class="activity-art" src="${a.iconData}" alt="">`;return icon(a.iconKey&&ICONS[a.iconKey]?a.iconKey:cat(a),'activity-art')}
function openDB(){return new Promise((ok,no)=>{let q=indexedDB.open(DB,1);q.onupgradeneeded=()=>{for(let n of STORES)if(!q.result.objectStoreNames.contains(n))q.result.createObjectStore(n,{keyPath:n==='meta'?'key':'id'})};q.onsuccess=()=>ok(q.result);q.onerror=()=>no(q.error)})}
function tx(names,mode,fn){return new Promise((ok,no)=>{let t=db.transaction(names,mode);try{fn(t)}catch(e){t.abort();no(e);return}t.oncomplete=()=>ok();t.onerror=()=>no(t.error);t.onabort=()=>no(t.error||Error('Speicherung fehlgeschlagen'))})}
function all(n){return new Promise((ok,no)=>{let q=db.transaction(n,'readonly').objectStore(n).getAll();q.onsuccess=()=>ok(q.result);q.onerror=()=>no(q.error)})}
const put=(n,x)=>tx([n],'readwrite',t=>t.objectStore(n).put(x));
const del=(n,k)=>tx([n],'readwrite',t=>t.objectStore(n).delete(k));
function mget(k,d){return S.meta.find(x=>x.key===k)?.value??d}
async function load(){[S.activities,S.entries,S.overrides,S.meta]=await Promise.all(STORES.map(all));S.activities.sort((a,b)=>(a.order??0)-(b.order??0));EM.clear();OM.clear();S.entries.forEach(e=>EM.set(e.id,e));S.overrides.forEach(e=>OM.set(e.id,e));S.theme=mget('theme','system');S.sound=mget('sound',true)!==false;S.colors={save:goodHex(mget('colorSave','#168a70'),'#168a70'),level:goodHex(mget('colorLevel','#a1ef45'),'#a1ef45')};S.timeout=Math.max(1,Math.min(10,Number(mget('packetTimeout',3))||3));theme()}
function goodHex(x,backup){return /^#[\da-fA-F]{6}$/.test(String(x))?x:backup}
function theme(){let dark=S.theme==='dark'||(S.theme==='system'&&matchMedia('(prefers-color-scheme:dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.style.setProperty('--save',S.colors.save);document.documentElement.style.setProperty('--level',S.colors.level);$('#themeMeta').content=dark?'#10121b':'#f7f8fd'}
function eFor(a,d){return EM.get(a.id+'|'+d)}
const created=a=>a.createdAt?.slice(0,10)||today();
function revision(a,d){let xs=[...(a.revisions||[])].sort((x,y)=>x.from.localeCompare(y.from));return xs.reverse().find(x=>x.from<=d)||xs[xs.length-1]||{rules:[],countXp:0}}
const rules=(a,d)=>revision(a,d).rules||[];
const countRate=(a,d)=>Math.max(0,Number(revision(a,d).countXp??0)||0);
function period(p,d){let t=date(d);if(p==='week')t.setDate(t.getDate()-(t.getDay()+6)%7);if(p==='month')t.setDate(1);if(p==='year')t.setMonth(0,1);let start=iso(t);if(p==='day')t.setDate(t.getDate()+1);if(p==='week')t.setDate(t.getDate()+7);if(p==='month')t.setMonth(t.getMonth()+1);if(p==='year')t.setFullYear(t.getFullYear()+1);return {start,end:iso(t)}}
function jump(p,d,n){let t=date(period(p,d).start);if(p==='day')t.setDate(t.getDate()+n);if(p==='week')t.setDate(t.getDate()+7*n);if(p==='month')t.setMonth(t.getMonth()+n);if(p==='year')t.setFullYear(t.getFullYear()+n);return iso(t)}
function days(start,end,max=370){let arr=[];for(let d=start;d<end&&arr.length<max;d=add(d,1))arr.push(d);return arr}
const order=['day','week','month','year'];
function ref(a,d,metric,dayOnly=false){let rs=rules(a,d);return (dayOnly?['day']:order).map(p=>rs.filter(r=>r.period===p&&valid(r[metric])).sort((x,y)=>a.kind==='reduce'?x[metric]-y[metric]:y[metric]-x[metric])[0]).find(Boolean)||null}
function status(a,d){let e=eFor(a,d);if(!e||!['yes','no'].includes(e.status))return 'pending';if(e.status==='no')return 'no';for(let r of rules(a,d).filter(r=>r.period==='day'))for(let metric of ['minutes','count'])if(valid(r[metric])&&valid(e[metric])&&(a.kind==='reduce'?e[metric]>r[metric]:e[metric]<r[metric]))return 'no';return 'yes'}
function assessment(a,r,d){let p=period(r.period,d),closed=p.end<=today();if(r.period==='day')return {status:status(a,p.start),closed,period:p,source:'day'};
 let end=p.end<add(today(),1)?p.end:add(today(),1),ds=days(p.start,end),totals={minutes:0,count:0},complete={minutes:true,count:true};
 for(let day of ds){let e=eFor(a,day);for(let k of ['minutes','count']){if(!valid(r[k]))continue;let v=e?.[k];if(k==='count'&&a.kind==='build'&&!valid(v)&&e?.status==='yes')v=1;if(k==='count'&&a.kind==='build'&&!valid(v)&&e?.status==='no')v=0;if(!valid(v))complete[k]=false;else totals[k]+=v}}
 let ks=['minutes','count'].filter(k=>valid(r[k])),s='pending';if(a.kind==='reduce'){if(ks.some(k=>totals[k]>r[k]))s='no';else if(closed&&ks.every(k=>complete[k]))s='yes'}else{if(ks.every(k=>totals[k]>=r[k]))s='yes';else if(closed&&ks.every(k=>complete[k]))s='no'}
 let override=OM.get(a.id+'|'+r.id+'|'+p.start);if(s!=='pending')return {status:s,closed,period:p,source:'auto',totals,complete,conflict:!!(override&&override.status!==s)};return {status:override?.status||s,closed,period:p,source:override?'manual':'auto',totals,complete};}
function streak(a,r){if(!r)return 0;let p=today(),v=assessment(a,r,p);if(v.status!=='yes')p=jump(r.period,p,-1);let n=0;for(let i=0;i<1200;i++,p=jump(r.period,p,-1)){if(p<period(r.period,created(a)).start)break;if(assessment(a,r,p).status==='yes')n++;else break}return n}
function bestStreak(a,r){if(!r)return 0;let p=period(r.period,created(a)).start,run=0,best=0;for(let i=0;i<1500&&p<=today();i++,p=jump(r.period,p,1)){let result=assessment(a,r,p);if(result.status==='yes'){run++;best=Math.max(run,best)}else if(result.closed)run=0}return best}
// Recalculate rewards from authoritative entries, not gestures, to prevent duplicated XP.
function rewardFor(a,metric){let result=0;if(a.kind==='build'){for(let e of S.entries){if(e.activityId!==a.id||e.date>today())continue;if(metric==='minutes'&&valid(e.minutes))result+=e.minutes/6;if(metric==='count'&&valid(e.count))result+=e.count*countRate(a,e.date)}return result}
 // Savings: for each metric use one shortest-period reference, never double count nested limits.
 const seen=new Set();for(let e of S.entries){if(e.activityId!==a.id||e.date>today())continue;let r=ref(a,e.date,metric);if(!r)continue;let p=period(r.period,e.date),key=r.id+'|'+p.start;if(seen.has(key))continue;seen.add(key);let delta=null,rate=metric==='minutes'?1/6:countRate(a,e.date);if(rate<=0)continue;
 if(r.period==='day'){if(e.status!=='no'&&valid(e[metric]))delta=Math.max(0,r[metric]-e[metric])}
 else if(p.end<=today()){let ds=days(p.start,p.end);if(ds.every(d=>d>=created(a)&&rules(a,d).some(x=>x.id===r.id&&x.period===r.period&&x[metric]===r[metric])&&valid(eFor(a,d)?.[metric]))){let used=ds.reduce((s,d)=>s+eFor(a,d)[metric],0);delta=Math.max(0,r[metric]-used)}}
 if(delta!==null)result+=delta*rate;
 }return result}
// Chronological XP ledger. Splits the CURRENT level bar by actual source instead of
// guessing from the lifetime percentages. One period reward is booked at period end.
function xpLedger(){let events=[];for(let a of S.activities){if(a.kind==='build'){for(let e of S.entries){if(e.activityId!==a.id||e.date>today())continue;let points=(valid(e.minutes)?e.minutes/6:0)+(valid(e.count)?e.count*countRate(a,e.date):0);if(points>0)events.push({when:e.date,kind:'level',xp:points});}continue}
 for(let metric of ['minutes','count']){let seen=new Set();for(let e of S.entries){if(e.activityId!==a.id||e.date>today())continue;let r=ref(a,e.date,metric);if(!r)continue;let p=period(r.period,e.date),key=r.id+'|'+p.start;if(seen.has(key))continue;seen.add(key);let rate=metric==='minutes'?1/6:countRate(a,e.date),delta=null;if(rate<=0)continue;
 if(r.period==='day'){if(e.status!=='no'&&valid(e[metric]))delta=Math.max(0,r[metric]-e[metric])}else if(p.end<=today()){let ds=days(p.start,p.end);if(ds.every(d=>d>=created(a)&&rules(a,d).some(x=>x.id===r.id&&x.period===r.period&&x[metric]===r[metric])&&valid(eFor(a,d)?.[metric]))){delta=Math.max(0,r[metric]-ds.reduce((sum,d)=>sum+eFor(a,d)[metric],0))}}
 if(delta!==null&&delta*rate>0)events.push({when:r.period==='day'?e.date:add(p.end,-1),kind:'save',xp:delta*rate});
 }} }
 return events.sort((x,y)=>x.when.localeCompare(y.when)||x.kind.localeCompare(y.kind));}
function xp(){let ledger=xpLedger(),save=0,level=0;for(let ev of ledger){if(ev.kind==='save')save+=ev.xp;else level+=ev.xp}let total=save+level,levelN=1+Math.floor((total+1e-7)/1000),progress=Math.max(0,total-(levelN-1)*1000),threshold=(levelN-1)*1000,acc=0,barSave=0,barLevel=0;
 for(let ev of ledger){let from=acc,to=acc+ev.xp;let contribution=Math.max(0,Math.min(total,to)-Math.max(threshold,from));if(contribution>0){if(ev.kind==='save')barSave+=contribution;else barLevel+=contribution}acc=to}
 return {save,level,total,levelN,progress,barSave,barLevel};}
function detail(a,d){let r=rules(a,d);return r.map(x=>`${a.kind==='reduce'?'Max.':'Mind.'} ${[valid(x.minutes)?x.minutes>=60&&x.minutes%60===0?x.minutes/60+' h':x.minutes+' min':null,valid(x.count)?x.count+'×':null].filter(Boolean).join(' & ')} / ${PERIODS[x.period]}`).join(' · ')||'Noch kein Ziel'}
function progressBar(){let x=xp();return `<div class="xphead"><span class="lvl">lvl. ${x.levelN}</span><div class="xp-center"><div id="xpTrack" class="xp-track" aria-label="${num(x.progress)} von 1000 XP"><span style="width:${x.barSave/10}%;background:var(--save)"></span><span style="width:${x.barLevel/10}%;background:var(--level)"></span></div><span class="xp-info">${num(x.progress)} / 1000 XP</span></div></div>`}
function nav(){let items=[['today','home','Heute'],['history','timeline','Zeitleiste'],['stats','stats','Statistik'],['settings','settings','Optionen']];$('#bottomNav').innerHTML=`<nav class="tabs" aria-label="Hauptnavigation">${items.map(([p,i,t])=>`<button data-action="tab" data-tab="${p}" class="tab ${S.page===p?'selected':''}" aria-label="${t}" ${S.page===p?'aria-current="page"':''}>${icon(i)}<small>${t}</small></button>`).join('')}</nav>`}
function appRender(){clearTimeout(timer);timer=0;$('#app').className=S.page==='today'?'app today-screen':'app';$('#app').innerHTML=S.page==='today'?todayPage():S.page==='history'?historyPage():S.page==='stats'?statsPage():settingsPage();nav();modalRender();if(S.packet)armTimer()}
function weekStrip(){let start=period('week',S.day).start;return `<div class="week-strip">${Array.from({length:7},(_,i)=>{let d=add(start,i),done=S.activities.filter(a=>status(a,d)!=='pending').length;return `<button data-action="date" data-date="${d}" class="weekday-btn ${S.day===d?'current':''} ${d===today()?'real-today':''}" ${d>today()?'disabled':''}><span>${WEEK[date(d).getDay()]}</span><b>${+d.slice(-2)}</b><i class="day-dot ${done?'done':''}"></i></button>`}).join('')}</div>`}
function openCards(){return S.activities.filter(a=>status(a,S.day)==='pending')}
function activeCardHTML(a){let r=rules(a,S.day),st=streak(a,r[0]),type=a.kind==='reduce'?'save':'level';return `<section class="deck-face ${type}" id="activeCard" data-id="${a.id}" tabindex="0" role="group" aria-label="${esc(a.name)}: links und rechts wechseln, oben geschafft, unten nicht geschafft"><div class="face-top"><span class="type-pill">${a.kind==='reduce'?'Sparen':'Leveln'}</span><button class="face-menu" data-action="edit" data-id="${a.id}" aria-label="${esc(a.name)} bearbeiten">${icon('dots')}</button></div><div class="face-center"><div class="category-badge">${catIcon(a)}</div><div class="category-text">${esc(CAT[cat(a)])}</div><h2>${esc(a.name)}</h2><p class="goal-text">${esc(detail(a,S.day))}</p></div><div class="face-bottom"><span>✧ ${st} ${r[0]?.period==='week'?'Wochen':r[0]?.period==='month'?'Monate':r[0]?.period==='year'?'Jahre':'Tage'} Streak</span><span class="card-indicator">${S.card+1} / ${openCards().length}</span></div></section>`}
function todayPage(){let cards=openCards();if(S.card>=cards.length)S.card=0;let a=cards[S.card],peeks=cards.length>1?Array.from({length:Math.min(2,cards.length-1)},(_,i)=>cards[(S.card+i+1)%cards.length]):[];
return `<div class="today-top"><div class="today-heading"><div><span class="eyebrow">PLAY YOUR DAY</span><h1>${S.day===today()?'Heute':esc(fmt(S.day,{weekday:'short',day:'numeric',month:'long'}))}</h1></div><div class="top-actions"><button class="weekjump" data-action="jump-week" data-value="-7" aria-label="Eine Woche zurück">‹</button><button class="weekjump" data-action="jump-week" data-value="7" aria-label="Eine Woche vor" ${add(S.day,7)>today()?'disabled':''}>›</button><button class="add-btn" data-action="new" aria-label="Aktivität hinzufügen">${icon('plus')}</button></div></div>${progressBar()}${weekStrip()}</div>${S.packet?packetPage():a?`<div class="deck-stage"><div class="deck-stack" id="deckStack">${peeks.slice().reverse().map((x,i)=>`<div class="peek peek-${peeks.length-i}" aria-hidden="true"><span>${catIcon(x)} ${esc(x.name)}</span></div>`).join('')}${activeCardHTML(a)}</div></div>`:`<div class="deck-stage"><div class="finished"><div class="finish-mark">${icon('spark')}</div><span class="eyebrow">ALLES AUSGESPIELT</span><h2>${S.activities.length?'Für diesen Tag erledigt!':'Dein Deck ist noch leer'}</h2><p>${S.activities.length?'Deine Karten sind sicher im Verlauf. Du kannst sie dort jederzeit nachtragen oder korrigieren.':'Lege deine erste Aktivität an und starte deinen Fortschritt.'}</p><button class="ghost-btn" data-action="${S.activities.length?'tab':'new'}" ${S.activities.length?'data-tab="history"':''}>${S.activities.length?'Zur Zeitleiste':'Erste Karte erstellen'}</button></div></div>`}<div class="deck-bottom">${S.packet?'<span>Pakete in die Leiste schleudern oder antippen</span>':`${cards.length} ${cards.length===1?'Karte':'Karten'} offen`}</div>`}
function packetPhases(a,d){let rs=rules(a,d),out=[];if(a.kind==='build'){if(rs.some(r=>valid(r.minutes)))out.push('minutes');if(rs.some(r=>valid(r.count)))out.push('count')}else{if(ref(a,d,'minutes',true))out.push('minutes');if(ref(a,d,'count',true))out.push('count')}return out}
function packetPage(){let q=S.packet,a=S.activities.find(x=>x.id===q.id);if(!a)return '';let isMin=q.phase==='minutes',packages=isMin?[1,5,10,30,60]:[1,5,10,50,100,500,1000];let sign=a.kind==='reduce'?'−':'+';let reference=ref(a,q.day,isMin?'minutes':'count',true),e=eFor(a,q.day),max=a.kind==='reduce'&&reference?reference[isMin?'minutes':'count']:Infinity,used=valid(e?.[isMin?'minutes':'count'])?e[isMin?'minutes':'count']:max,remaining=a.kind==='reduce'?Math.max(0,used):Infinity;return `<section class="packet-stage ${a.kind==='reduce'?'save':'level'}"><div class="package-intro"><div class="small-category">${catIcon(a)} ${esc(a.name)}</div><span class="eyebrow">${isMin?'ZEITPAKETE':'ANZAHLPACKETE'}</span><h2>${isMin?(a.kind==='reduce'?'Zeit gespart':'Zeit investiert'):(a.kind==='reduce'?'Einheiten gespart':'Zusätzliche Einheiten')}</h2><p>${isMin?'+10 XP pro Stunde':`${num(countRate(a,q.day),2)} XP je Einheit`}</p></div><div class="packet-grid">${packages.map(n=>`<button class="packet-chip ${Number.isFinite(remaining)&&n>remaining?'unavailable':''}" data-packet="${n}" ${n>remaining?'disabled':''} aria-label="${sign}${n} ${isMin?'Minuten':'Einheiten'}"><strong>${sign}${n}</strong><small>${isMin?'min':'×'}</small></button>`).join('')}</div><div class="packet-footer"><span>${q.phases.indexOf(q.phase)+1} / ${q.phases.length}</span><button data-action="skip-packets" class="skip-btn" aria-label="Paketphase überspringen">${icon('close')}</button></div></section>`}
function heading(top,title,addButton=false){return `<div class="section-head"><div class="eyebrow">${esc(top)}</div><div class="head-flex"><h1>${esc(title)}</h1>${addButton?`<button class="add-btn" data-action="new">${icon('plus')}</button>`:''}</div></div>`}
function historyPage(){let p=S.history;return `${heading('DEIN VERLAUF','Zeitleiste',true)}<div class="segments">${[['day','Tag'],['week','Woche'],['month','Monat'],['year','Jahr'],['all','Gesamt']].map(([v,t])=>`<button class="seg ${p===v?'chosen':''}" data-action="history" data-value="${v}">${t}</button>`).join('')}</div>${p==='all'?allHistory():`<div class="range-nav"><button data-action="shift" data-value="-1">‹</button><strong>${p==='day'?fmt(S.day):p==='week'?`${fmt(period('week',S.day).start,{day:'numeric',month:'short'})} – ${fmt(add(period('week',S.day).end,-1),{day:'numeric',month:'short'})}`:p==='month'?fmt(S.day,{month:'long',year:'numeric'}):fmt(S.day,{year:'numeric'})}</strong><button data-action="shift" data-value="1" ${jump(p,S.day,1)>today()?'disabled':''}>›</button></div>${p==='day'?historyDay():p==='week'?historyWeek():p==='month'?historyMonth():historyYear()}${p!=='day'?periodRows(p,S.day):''}`}`}
function historyDay(){return `<div class="list-card">${S.activities.map(a=>{let e=eFor(a,S.day),s=status(a,S.day);return `<button class="history-row" data-action="edit-entry" data-id="${a.id}" data-date="${S.day}"><span class="mini-symbol ${a.kind==='reduce'?'save':'level'}">${catIcon(a)}</span><span class="row-main"><b>${esc(a.name)}</b><small>${esc(detail(a,S.day))}</small></span><span class="status ${s}">${s==='yes'?'✓':s==='no'?'–':'○'}</span><span class="chev">›</span></button>`}).join('')||'<p class="quiet">Noch keine Aktivitäten angelegt.</p>'}</div><p class="quiet">Eintrag antippen: Status, Minuten, Anzahl und Notizen nachträglich bearbeiten.</p>${periodRows('day',S.day)}<h3 class="small-heading">Aktivitäten verwalten</h3><div class="list-card">${S.activities.map(a=>`<div class="history-row"><span class="row-main"><b>${esc(a.name)}</b><small>${esc(CAT[cat(a)])}</small></span><button class="mini-action" data-action="move" data-id="${a.id}" data-value="-1">↑</button><button class="mini-action" data-action="move" data-id="${a.id}" data-value="1">↓</button><button class="mini-action" data-action="edit" data-id="${a.id}">${icon('edit')}</button></div>`).join('')}</div>`}
function historyWeek(){let start=period('week',S.day).start;return `<div class="list-card">${days(start,add(start,7),7).map(d=>`<button class="history-row" data-action="open-day" data-date="${d}" ${d>today()?'disabled':''}><span class="date-box">${WEEK[date(d).getDay()]}<strong>${+d.slice(-2)}</strong></span><span class="row-main"><b>${esc(fmt(d,{weekday:'long',day:'numeric',month:'short'}))}</b><small>${S.activities.filter(a=>status(a,d)!=='pending').length} / ${S.activities.length} Karten gespielt</small></span><span class="chev">›</span></button>`).join('')}</div>`}
function historyMonth(){let b=period('month',S.day),offset=(date(b.start).getDay()+6)%7;return `<div class="list-card"><div class="month-grid">${['M','D','M','D','F','S','S'].map(s=>`<span class="cap">${s}</span>`).join('')}${Array.from({length:offset},()=>'<span></span>').join('')}${days(b.start,b.end,32).map(d=>{let s=dayState(d);return `<button data-action="open-day" data-date="${d}" class="month-day ${s}" ${d>today()?'disabled':''}>${+d.slice(-2)}</button>`}).join('')}</div></div>`}
function historyYear(){let y=+S.day.slice(0,4);return `<div class="year-grid">${Array.from({length:12},(_,m)=>{let d=iso(new Date(y,m,1,12)),b=period('month',d);let played=days(b.start,b.end,32).filter(x=>x<=today()&&dayState(x)==='yes').length;return `<button data-action="open-month" data-date="${d}" ${d>today()?'disabled':''}><span>${fmt(d,{month:'short'})}</span><strong>${played}</strong><small>volle Tage</small></button>`}).join('')}</div>`}
function dayState(d){if(!S.activities.length)return 'pending';let xs=S.activities.map(a=>status(a,d));return xs.every(x=>x==='yes')?'yes':xs.every(x=>x==='pending')?'pending':xs.some(x=>x==='no')?'no':'part'}
function periodRows(p,d){let rows=S.activities.flatMap(a=>rules(a,d).filter(r=>r.period===p).map(r=>({a,r,ev:assessment(a,r,d)})));if(!rows.length)return `<p class="quiet">Keine ${PERIODS[p]}-Ziele definiert.</p>`;return `<h3 class="small-heading">Ziele · ${PERIODS[p]}</h3><div class="list-card">${rows.map(({a,r,ev})=>`<div class="history-row"><span class="row-main"><b>${esc(a.name)}</b><small>${esc(detailRule(a,r))}${ev.source==='manual'?' · manuell':''}${ev.conflict?' · Widerspruch':''}</small></span><span class="status ${ev.status}">${ev.status==='yes'?'✓':ev.status==='no'?'–':'○'}</span>${p!=='day'&&ev.closed&&(ev.status==='pending'||ev.source==='manual')?`<button class="mini-action" data-action="period" data-id="${a.id}" data-rule="${r.id}" data-date="${d}" data-period="${p}">Bestätigen</button>`:''}</div>`).join('')}</div>`}
function detailRule(a,r){return `${a.kind==='reduce'?'Max.':'Mind.'} ${[valid(r.minutes)?num(r.minutes,0)+' min':null,valid(r.count)?num(r.count,0)+'×':null].filter(Boolean).join(' & ')} / ${PERIODS[r.period]}`}
function allHistory(){let x=xp();let hoursSaved=S.activities.filter(a=>a.kind==='reduce').reduce((sum,a)=>sum+rewardFor(a,'minutes')*6,0),hoursBuild=S.activities.filter(a=>a.kind==='build').reduce((sum,a)=>sum+rewardFor(a,'minutes')*6,0);return `<section class="profile"><span class="eyebrow">DEIN CHARAKTER</span><div class="profile-level">lvl. ${x.levelN}</div>${progressBar()}<div class="stat-tiles"><div><small>Gesamt-XP</small><b>${num(x.total)}</b></div><div><small>Karten gespielt</small><b>${S.entries.filter(e=>e.status==='yes'||e.status==='no').length}</b></div><div><small>Gespart</small><b>${num(hoursSaved/60)} h</b></div><div><small>Investiert</small><b>${num(hoursBuild/60)} h</b></div></div><div class="two-bars"><span><i style="background:var(--save)"></i> Sparen ${num(x.save)} XP</span><span><i style="background:var(--level)"></i> Leveln ${num(x.level)} XP</span></div></section><div class="list-card">${S.activities.map(a=>`<div class="history-row"><span class="mini-symbol">${catIcon(a)}</span><span class="row-main"><b>${esc(a.name)}</b><small>${num(rewardFor(a,'minutes')+rewardFor(a,'count'))} XP</small></span><button class="mini-action" data-action="edit" data-id="${a.id}">${icon('edit')}</button></div>`).join('')}</div>`}
function statsPage(){let x=xp();let completed=S.entries.filter(e=>e.status==='yes').length,missed=S.entries.filter(e=>e.status==='no').length,rate=completed+missed?Math.round(100*completed/(completed+missed)):0;return `${heading('DEINE ENTWICKLUNG','Statistik')}<div class="stat-tiles big"><div><small>Erfolgstage</small><b>${completed}</b></div><div><small>Erfolgsquote</small><b>${rate}%</b></div><div><small>Gesamt-XP</small><b>${num(x.total)}</b></div><div><small>Aktuelles Level</small><b>${x.levelN}</b></div></div><h3 class="small-heading">Streaks und XP je Aktivität</h3><div class="list-card">${S.activities.map(a=>{let r=rules(a,today())[0];return `<div class="history-row"><span class="mini-symbol ${a.kind==='reduce'?'save':'level'}">${catIcon(a)}</span><span class="row-main"><b>${esc(a.name)}</b><small>✧ ${streak(a,r)} aktuell · ${bestStreak(a,r)} Rekord · ${r?.period==='week'?'Wochen':r?.period==='month'?'Monate':r?.period==='year'?'Jahre':'Tage'} Streak</small></span><b>${num(rewardFor(a,'minutes')+rewardFor(a,'count'))} XP</b></div>`}).join('')}</div><p class="quiet">Ein einzelner Rückschlag löscht deine verdienten XP nicht. Nachträglich geänderte Mengen aktualisieren die Berechnung.</p>`}
function settingsPage(){return `${heading('DEINE APP','Optionen')}<div class="list-card settings-list"><div class="setting"><label for="settingTheme">Darstellung</label><select id="settingTheme" data-setting="theme"><option value="system" ${S.theme==='system'?'selected':''}>System</option><option value="light" ${S.theme==='light'?'selected':''}>Hell</option><option value="dark" ${S.theme==='dark'?'selected':''}>Dunkel</option></select></div><div class="setting"><label for="colorSave">Sparen · Farbe</label><input type="color" id="colorSave" data-setting="colorSave" value="${S.colors.save}"></div><div class="setting"><label for="colorLevel">Leveln · Farbe</label><input type="color" id="colorLevel" data-setting="colorLevel" value="${S.colors.level}"></div><div class="setting"><label for="timeSetting">Paket-Pause (1–10 s)<span class="sub-label">Automatischer Wechsel nach Inaktivität</span></label><div class="range-setting"><input id="timeSetting" data-setting="packetTimeout" type="range" min="1" max="10" step="1" value="${S.timeout}"><strong id="timeoutLabel">${S.timeout} s</strong></div></div><div class="setting"><label for="soundSetting">Erfolgssounds</label><input type="checkbox" id="soundSetting" data-setting="sound" ${S.sound?'checked':''}></div></div><h3 class="small-heading">Privat & lokal</h3><div class="list-card"><button class="history-row command" data-action="export">Backup exportieren <span>↓</span></button><button class="history-row command" data-action="import">Backup importieren <span>↑</span></button><button class="history-row command danger" data-action="erase">Alle lokalen Inhalte löschen <span>×</span></button></div><p class="quiet">Progress speichert Aktivitäten und Einträge lokal auf diesem Gerät. Keine Konten und keine Tracking-Dienste. JSON-Backups enthalten deine Daten unverschlüsselt – bitte sicher aufbewahren. iOS kann Website-Daten entfernen, deshalb regelmäßig sichern.</p><div class="version">Progress 0.3 · Play your day</div>`}
function sheet(title,sub,html){$('#modalRoot').innerHTML=`<div class="sheet-shade" data-action="dismiss"><div class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="handle"></div><div class="sheet-title"><div><span class="eyebrow">${esc(sub)}</span><h2>${esc(title)}</h2></div><button data-action="close" class="sheet-x" aria-label="Schließen">×</button></div>${html}</div></div>`}
function modalRender(){if(!S.modal){$('#modalRoot').innerHTML='';return}if(S.modal.type==='activity')activityModal();if(S.modal.type==='entry')entryModal();if(S.modal.type==='period')periodModal()}
function close(){S.modal=null;S.entryStatus=null;S.ruleDraft=[];modalRender()}
function ruleFields(r,i){return `<div class="rule-editor" data-rule-index="${i}"><div class="rule-title"><b>Ziel ${i+1}</b><button type="button" data-action="remove-rule">Entfernen</button></div><label>Zeitraum<select class="rule-period">${Object.entries(PERIODS).map(([k,v])=>`<option value="${k}" ${r.period===k?'selected':''}>${v}</option>`).join('')}</select></label><div class="two-input"><label>Minuten<input class="rule-minutes" type="number" min="0" max="1000000" inputmode="numeric" value="${r.minutes??''}" placeholder="Optional"></label><label>Anzahl<input class="rule-count" type="number" min="0" max="1000000" inputmode="numeric" value="${r.count??''}" placeholder="Optional"></label></div></div>`}
function activityModal(){let a=S.modal.id?S.activities.find(x=>x.id===S.modal.id):null,kind=a?.kind||S.modal.kind||'build';if(!S.ruleDraft.length)S.ruleDraft=structuredClone(a?rules(a,today()):[{id:id(),period:'day',minutes:kind==='reduce'?60:30,count:null}]);let iconSel=a?.iconKey||'',title=a?'Karte bearbeiten':'Neue Karte';let html=`<form id="activityForm"><label>Name<input required name="name" maxlength="70" value="${esc(a?.name||'')}" placeholder="z. B. Französisch"></label><label>Typ<select name="kind" ${a?'disabled':''}><option value="reduce" ${kind==='reduce'?'selected':''}>Sparen · maximal</option><option value="build" ${kind==='build'?'selected':''}>Leveln · mindestens</option></select></label><label>Lebensbereich<select name="category">${Object.entries(CAT).map(([k,v])=>`<option value="${k}" ${(a?.category||cat(a||{kind}))===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>Kartensymbol<select name="iconKey"><option value="">Kategorie-Symbol verwenden</option>${Object.entries(CAT).map(([k,v])=>`<option value="${k}" ${iconSel===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>Eigenes Bild als Icon (optional)<input name="iconFile" type="file" accept="image/png,image/jpeg,image/webp"></label>${a?.iconData?`<label class="checkbox-line"><input type="checkbox" name="removeIcon"> Eigenes Bild entfernen</label>`:''}<h3>Deine Ziele</h3><p class="form-hint">Kombiniere mehrere Tages-, Wochen-, Monats- oder Jahresgrenzen.</p><div id="ruleFields">${S.ruleDraft.map(ruleFields).join('')}</div><button type="button" class="plain-btn" data-action="add-rule">+ Weitere Zielregel</button><label>XP je Einheit / Anzahl<input type="number" name="countXp" min="0" max="100000" step="0.01" inputmode="decimal" value="${esc(revision(a||{revisions:[]},today()).countXp??0)}"></label><p class="form-hint">Zusätzliche XP für Anzahlen; 0 = nur Zeit-XP. 60 Minuten ergeben weiterhin 10 XP.</p><div class="form-actions"><button type="button" class="plain-btn" data-action="close">Abbrechen</button><button class="primary-btn" type="submit">Speichern</button></div>${a?`<button type="button" class="delete-btn" data-action="remove-activity" data-id="${a.id}">Aktivität löschen</button>`:''}</form>`;sheet(title,'DEIN KARTENDECK',html)}
function entryModal(){let {id:aId,day}=S.modal,a=S.activities.find(x=>x.id===aId);if(!a)return close();let e=eFor(a,day),s=S.entryStatus??e?.status??'pending';let html=`<div class="form-hint">${esc(fmt(day))}. Änderungen wirken sich sofort auf die XP und die Streak aus.</div><div class="status-choices">${[['yes','✓ Erreicht'],['no','– Nicht erreicht'],['pending','○ Offen']].map(([v,t])=>`<button class="status-option ${s===v?'on':''}" type="button" data-action="entry-status" data-value="${v}">${t}</button>`).join('')}</div><form id="entryForm" data-id="${a.id}" data-day="${day}"><div class="two-input"><label>Tatsächliche Minuten<input name="minutes" type="number" min="0" max="1000000" inputmode="numeric" value="${e?.minutes??''}" placeholder="Unbekannt"></label><label>Tatsächliche Anzahl<input name="count" type="number" min="0" max="1000000" inputmode="numeric" value="${e?.count??''}" placeholder="Unbekannt"></label></div><label>Kommentar<textarea name="comment" maxlength="5000" placeholder="Was war besonders?">${esc(e?.comment||'')}</textarea></label><p class="form-hint">Unbekannt ist nicht dasselbe wie null. Beim Speichern werden Zeitpaket-Angaben durch diese exakten Werte ersetzt.</p><div class="form-actions"><button type="button" class="plain-btn" data-action="close">Abbrechen</button><button class="primary-btn" type="submit">Speichern</button></div></form>`;sheet(a.name,'ZEITLEISTE · TAGESEINTRAG',html)}
function periodModal(){let {id:aId,ruleId,day,p}=S.modal,a=S.activities.find(x=>x.id===aId),r=a&&rules(a,day).find(r=>r.id===ruleId);if(!r)return close();let b=period(p,day),o=OM.get(aId+'|'+ruleId+'|'+b.start);let html=`<p class="form-hint">${esc(detailRule(a,r))}. Automatische Auswertung ist derzeit nicht eindeutig. Du kannst den abgeschlossenen Zeitraum bestätigen.</p><div class="status-choices">${[['yes','✓ Erreicht'],['no','– Nicht erreicht']].map(([v,t])=>`<button type="button" class="status-option ${S.entryStatus===v?'on':''}" data-action="entry-status" data-value="${v}">${t}</button>`).join('')}</div><form id="periodForm"><label>Notiz<textarea name="comment">${esc(o?.comment||'')}</textarea></label><div class="form-actions"><button type="button" class="plain-btn" data-action="close">Abbrechen</button><button type="submit" class="primary-btn">Bestätigen</button></div></form>${o?'<button class="delete-btn" data-action="delete-override">Bestätigung entfernen</button>':''}`;sheet('Zeitraum bestätigen','MANUELLE AUSWERTUNG',html)}
function parseNumber(v,field){v=String(v||'').trim();if(!v)return null;if(!/^\d+$/.test(v)||+v>1000000)throw Error(`Ungültige Angabe für ${field}.`);return +v}
function readRuleFields(){for(let el of $$('[data-rule-index]')){let r=S.ruleDraft[+el.dataset.ruleIndex];if(!r)continue;r.period=el.querySelector('.rule-period').value;r.minutes=parseNumber(el.querySelector('.rule-minutes').value,'Minuten');r.count=parseNumber(el.querySelector('.rule-count').value,'Anzahl')}}
async function imageData(file){if(!file)return null;if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Bitte PNG, JPG oder WebP wählen.');if(file.size>8e6)throw Error('Bild zu groß (max. 8 MB).');let bmp=await createImageBitmap(file);let c=document.createElement('canvas'),ctx=c.getContext('2d');c.width=160;c.height=160;let scale=Math.max(160/bmp.width,160/bmp.height),w=bmp.width*scale,h=bmp.height*scale;ctx.drawImage(bmp,(160-w)/2,(160-h)/2,w,h);bmp.close?.();return c.toDataURL('image/png')}
async function saveActivity(form){readRuleFields();let name=form.elements.name.value.trim();if(!name)throw Error('Bitte Namen eingeben.');if(!S.ruleDraft.length||S.ruleDraft.some(r=>!valid(r.minutes)&&!valid(r.count)))throw Error('Jede Zielregel benötigt Minuten und/oder eine Anzahl.');let rawRate=String(form.elements.countXp.value).trim(),rate=Number(rawRate);if(!Number.isFinite(rate)||rate<0||rate>100000)throw Error('XP je Einheit sind ungültig.');let now=new Date().toISOString(),old=S.modal.id?S.activities.find(x=>x.id===S.modal.id):null;let a=old?structuredClone(old):{id:id(),createdAt:now,order:S.activities.length,revisions:[]};a.name=name;a.kind=old?.kind||form.elements.kind.value;a.category=form.elements.category.value;a.iconKey=form.elements.iconKey.value;a.updatedAt=now;let img=form.elements.iconFile.files[0];if(img)a.iconData=await imageData(img);else if(form.elements.removeIcon?.checked)a.iconData=null;
 a.revisions=a.revisions.filter(x=>x.from!==today());a.revisions.push({from:today(),rules:structuredClone(S.ruleDraft),countXp:rate});a.revisions.sort((x,y)=>x.from.localeCompare(y.from));await put('activities',a);close();await load();S.day=today();S.page='today';S.packet=null;S.card=Math.max(0,openCards().findIndex(x=>x.id===a.id));appRender();pop(old?'Karte aktualisiert':'Karte hinzugefügt')}
async function saveEntry(form){let a=S.activities.find(x=>x.id===form.dataset.id),day=form.dataset.day;if(!a||day>today())return;let minutes=parseNumber(form.elements.minutes.value,'Minuten'),count=parseNumber(form.elements.count.value,'Anzahl'),s=S.entryStatus??eFor(a,day)?.status??'pending';if(s==='yes')for(let r of rules(a,day).filter(r=>r.period==='day'))for(let metric of ['minutes','count'])if(valid(r[metric])&&valid({minutes,count}[metric])&&(a.kind==='reduce'?{minutes,count}[metric]>r[metric]:{minutes,count}[metric]<r[metric]))throw Error('Der Messwert widerspricht deinem Tagesziel. Bitte Status korrigieren.');let prev=xp(),old=eFor(a,day)||{};await put('entries',{...old,id:a.id+'|'+day,activityId:a.id,date:day,status:s==='pending'?null:s,minutes,count,comment:String(form.elements.comment.value).slice(0,5000),updatedAt:new Date().toISOString()});close();await load();appRender();rewardEvent(prev,xp())}
async function savePeriod(form){let {id:aId,ruleId,day,p}=S.modal,a=S.activities.find(x=>x.id===aId),r=a&&rules(a,day).find(r=>r.id===ruleId);if(!r||!['yes','no'].includes(S.entryStatus))throw Error('Bitte erreichte oder nicht erreichte Ziele auswählen.');let ev=assessment(a,r,day);if(!ev.closed||(ev.status!=='pending'&&ev.source!=='manual'))throw Error('Dieser Zeitraum ist automatisch bestimmt oder noch offen.');let start=period(p,day).start;await put('overrides',{id:aId+'|'+ruleId+'|'+start,activityId:aId,ruleId,period:p,start,status:S.entryStatus,comment:String(form.elements.comment.value).slice(0,5000),updatedAt:new Date().toISOString()});close();await load();appRender()}
function buildBase(a,d){let mins=ref(a,d,'minutes',true)?.minutes??null,c=ref(a,d,'count',true)?.count??null;if(c===null&&rules(a,d).some(r=>r.period!=='day'&&valid(r.count)))c=1;return {minutes:mins,count:c}}
async function playCard(aId,success){if(S.locked||S.packet||S.page!=='today')return;let a=S.activities.find(x=>x.id===aId);if(!a||status(a,S.day)!=='pending')return;S.locked=true;let prev=xp(),old=eFor(a,S.day)||{},base=success&&a.kind==='build'?buildBase(a,S.day):{minutes:null,count:null};let e={...old,id:a.id+'|'+S.day,activityId:a.id,date:S.day,status:success?'yes':'no',minutes:success?base.minutes:null,count:success?base.count:null,comment:old.comment||'',updatedAt:new Date().toISOString()};try{await put('entries',e);await load();if(success){tone(false);buzz();let phases=packetPhases(a,S.day);if(phases.length){S.packet={id:a.id,day:S.day,phase:phases[0],phases};S.card=Math.min(S.card,Math.max(0,openCards().length-1))}else S.card=Math.min(S.card,Math.max(0,openCards().length-1));}else{S.card=Math.min(S.card,Math.max(0,openCards().length-1))}S.locked=false;appRender();rewardEvent(prev,xp(),false)}catch(err){S.locked=false;throw err}}
function nextPacketPhase(){clearTimeout(timer);if(!S.packet)return;let q=S.packet,i=q.phases.indexOf(q.phase);if(i<q.phases.length-1){q.phase=q.phases[i+1];S.packetBusy=false;appRender()}else{S.packet=null;S.packetBusy=false;appRender()}}
function armTimer(){clearTimeout(timer);if(!S.packet||S.packetBusy||S.modal)return;timer=setTimeout(()=>nextPacketPhase(),S.timeout*1000)}
async function sendPacket(amount,origin){if(!S.packet||S.packetBusy||S.locked)return;let q=S.packet,a=S.activities.find(x=>x.id===q.id);if(!a)return;let metric=q.phase==='minutes'?'minutes':'count',old=eFor(a,q.day),r=ref(a,q.day,metric,true);if(a.kind==='reduce'&&(!r||(valid(old?.[metric])?old[metric]:r[metric])<amount))return;
 S.packetBusy=true;clearTimeout(timer);let before=xp();let updated={...old};if(a.kind==='reduce')updated[metric]=(valid(old?.[metric])?old[metric]:r[metric])-amount;else updated[metric]=(valid(old?.[metric])?old[metric]:0)+amount;updated.updatedAt=new Date().toISOString();
 try{let anim=flyPacket(origin,metric,amount);await put('entries',updated);await load();await anim;let after=xp();S.packetBusy=false;appRender();rewardEvent(before,after,true);armTimer()}catch(e){S.packetBusy=false;appRender();throw e}}
function flyPacket(source,metric,amount){return new Promise(resolve=>{let target=$('#xpTrack'),box=source?.getBoundingClientRect(),end=target?.getBoundingClientRect();if(!box||!end){resolve();return}let clone=document.createElement('div');clone.className='flying-chip';clone.textContent=(S.activities.find(a=>a.id===S.packet.id)?.kind==='reduce'?'−':'+')+amount+(metric==='minutes'?' min':'');clone.style.left=box.left+'px';clone.style.top=box.top+'px';clone.style.width=box.width+'px';clone.style.height=box.height+'px';document.body.append(clone);requestAnimationFrame(()=>{clone.style.transform=`translate(${end.left+end.width*.5-(box.left+box.width*.5)}px,${end.top+end.height*.5-(box.top+box.height*.5)}px) scale(.18) rotate(-14deg)`;clone.style.opacity='0.1'});setTimeout(()=>{clone.remove();resolve()},430)})}
function rewardEvent(before,after,popup=true){let difference=after.total-before.total;if(after.levelN>before.levelN){levelUp(after.levelN);return}if(popup&&difference>0.0001)showXpPop(difference);}
function showXpPop(delta){let target=$('#xpTrack')?.getBoundingClientRect();if(!target)return;let el=document.createElement('div');el.className='xp-pop';el.textContent='+'+num(delta,2)+' XP';el.style.left=Math.min(window.innerWidth-105,target.left+target.width*.6)+'px';el.style.top=Math.max(8,target.top-29)+'px';document.body.append(el);tone(false);setTimeout(()=>el.remove(),950)}
function levelUp(level){clearTimeout(timer);$('#celebrateRoot').innerHTML=`<div class="level-up" role="dialog" aria-label="Level aufgestiegen"><div class="level-glow"></div><div class="level-center"><span class="eyebrow">LEVEL UP!</span><div class="level-big">${level}</div><p>Dein Charakter wächst mit dir.</p><button data-action="dismiss-level" class="primary-btn">Weiter</button></div></div>`;tone(true);buzz()}
function pop(msg){let p=document.createElement('div');p.className='toast';p.textContent=msg;$('#celebrateRoot').append(p);setTimeout(()=>p.remove(),1700)}
function buzz(){try{navigator.vibrate?.(18)}catch{}}
function tone(big){if(!S.sound)return;try{let C=window.AudioContext||window.webkitAudioContext;if(!C)return;audio??=new C;if(audio.state==='suspended')audio.resume();let freqs=big?[523,659,784,1047]:[659,880];freqs.forEach((f,i)=>{let o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*.105;o.type='sine';o.frequency.setValueAtTime(f,t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(big?.10:.05,t+.025);g.gain.exponentialRampToValueAtTime(.0001,t+.21);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+.23)})}catch{}}
async function setting(k,v){let key=k==='colorSave'?'colorSave':k==='colorLevel'?'colorLevel':k;await put('meta',{key,value:v});await load();appRender()}
async function exportData(){let blob=new Blob([JSON.stringify({format:'progress-local-backup',version:1,exportedAt:new Date().toISOString(),data:{activities:S.activities,entries:S.entries,overrides:S.overrides,meta:S.meta}},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Progress-Backup-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),25000)}
async function importData(file){if(file.size>40*1024*1024)throw Error('Backup zu groß (max. 40 MB).');let obj=JSON.parse(await file.text());if(obj.format!=='progress-local-backup'||obj.version!==1||!obj.data||!STORES.every(k=>Array.isArray(obj.data[k])))throw Error('Kein unterstütztes Progress-Backup.');for(let n of STORES){if(obj.data[n].length>50000)throw Error('Zu viele Datensätze.');for(let x of obj.data[n])if(!x||typeof x!=='object'||typeof x[n==='meta'?'key':'id']!=='string')throw Error('Ungültiger Datensatz.')}if(!confirm(`Backup mit ${obj.data.activities.length} Aktivitäten importieren? Alle Daten auf diesem Gerät werden ERSETZT.`))return;await tx(STORES,'readwrite',t=>{for(let n of STORES){let s=t.objectStore(n);s.clear();obj.data[n].forEach(x=>s.put(x))}});close();S.packet=null;await load();S.day=today();S.page='today';S.card=0;appRender();pop('Backup wiederhergestellt')}
async function eraseData(){if(!confirm('Wirklich alle Aktivitäten und Einträge löschen? Erstelle vorher ein Backup.'))return;if(!confirm('Diese Aktion kann nicht rückgängig gemacht werden. Fortfahren?'))return;await tx(['activities','entries','overrides','meta'],'readwrite',t=>{['activities','entries','overrides'].forEach(n=>t.objectStore(n).clear());t.objectStore('meta').put({key:'initialized',value:true})});S.packet=null;await load();appRender()}
function initial(){let now=new Date().toISOString();return [{name:'Social Media',kind:'reduce',category:'digital',rule:{minutes:60,count:null,period:'day'}},{name:'Sport',kind:'build',category:'fitness',rule:{minutes:30,count:null,period:'day'}},{name:'Französisch',kind:'build',category:'learning',rule:{minutes:20,count:null,period:'day'}}].map((a,i)=>({id:id(),name:a.name,kind:a.kind,category:a.category,createdAt:now,order:i,revisions:[{from:today(),rules:[{id:id(),...a.rule}],countXp:0}]}))}
async function init(){try{db=await openDB();await load();if(!S.meta.some(x=>x.key==='initialized')){await tx(['activities','meta'],'readwrite',t=>{initial().forEach(a=>t.objectStore('activities').put(a));t.objectStore('meta').put({key:'initialized',value:true})});await load()}appRender();if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(console.warn)}catch(err){$('#app').innerHTML=`<div class="fatal"><h2>Lokaler Speicher nicht verfügbar</h2><p>${esc(err.message)}</p><p>Bitte über Safari und eine HTTPS-Adresse öffnen.</p></div>`;console.error(err)}}
// UI events
function go(p){clearTimeout(timer);S.packet=null;S.page=p;S.card=0;S.modal=null;appRender();window.scrollTo(0,0)}
function animateCard(direction,done){let el=$('#activeCard');if(!el){done();return}S.locked=true;el.classList.add('leaving');let dx=direction==='left'?-innerWidth:direction==='right'?innerWidth:0,dy=direction==='up'?-innerHeight:direction==='down'?innerHeight:0;el.style.transform=`translate3d(${dx}px,${dy}px,0) rotate(${dx?dx*.015:0}deg)`;el.style.opacity='0';setTimeout(()=>{S.locked=false;done()},250)}
function rotateCards(shift){let n=openCards().length;if(!n)return;S.card=(S.card+shift+n)%n;appRender()}
// Dedicated gesture area: does not compete with page scrolling, which is disabled only for today.
document.addEventListener('pointerdown',e=>{let pack=e.target.closest('[data-packet]');if(pack&&!pack.disabled&&S.packet&&!S.packetBusy){clearTimeout(timer);gesture={type:'packet',node:pack,pid:e.pointerId,x:e.clientX,y:e.clientY,dx:0,dy:0};try{pack.setPointerCapture(e.pointerId)}catch{};return}let card=e.target.closest('#activeCard');if(!card||e.target.closest('button')||S.packet||S.locked||S.modal)return;gesture={type:'card',node:card,pid:e.pointerId,x:e.clientX,y:e.clientY,dx:0,dy:0};try{card.setPointerCapture(e.pointerId)}catch{}});
document.addEventListener('pointermove',e=>{if(!gesture||e.pointerId!==gesture.pid)return;let g=gesture;g.dx=e.clientX-g.x;g.dy=e.clientY-g.y;if(Math.abs(g.dx)+Math.abs(g.dy)<8)return;if(e.cancelable)e.preventDefault();if(g.type==='card')g.node.style.transform=`translate3d(${g.dx*.9}px,${g.dy*.9}px,0) rotate(${g.dx*.035}deg)`;else{g.node.style.transform=`translate3d(${g.dx*.65}px,${g.dy*.65}px,0) scale(1.06)`;g.node.classList.add('held')}});
document.addEventListener('pointerup',e=>{if(!gesture||e.pointerId!==gesture.pid)return;let g=gesture;gesture=null;g.node.style.transform='';g.node.classList.remove('held');if(g.type==='packet'){if(g.dy< -24||Math.abs(g.dx)+Math.abs(g.dy)<15)sendPacket(+g.node.dataset.packet,g.node).catch(errorAlert);else armTimer();return}if(Math.max(Math.abs(g.dx),Math.abs(g.dy))<65)return;if(Math.abs(g.dx)>Math.abs(g.dy)){animateCard(g.dx<0?'left':'right',()=>rotateCards(g.dx<0?1:-1));return}let up=g.dy<0;animateCard(up?'up':'down',()=>playCard(g.node.dataset.id,up).catch(errorAlert))});
document.addEventListener('pointercancel',()=>{if(gesture){gesture.node.style.transform='';gesture.node.classList.remove('held');gesture=null;if(S.packet)armTimer()}});
function errorAlert(e){console.error(e);alert('Fehler: '+e.message);S.locked=false;S.packetBusy=false;appRender()}
document.addEventListener('click',async e=>{let el=e.target.closest('[data-action]');if(!el)return;let action=el.dataset.action;try{
 if(action==='dismiss'){if(e.target===el)close();return}if(action==='close'){close();return}if(action==='tab'){go(el.dataset.tab);return}
 if(action==='new'){S.modal={type:'activity',kind:'build'};S.ruleDraft=[];modalRender();return}
 if(action==='edit'){S.modal={type:'activity',id:el.dataset.id};S.ruleDraft=[];modalRender();return}
 if(action==='date'){S.day=el.dataset.date;S.packet=null;S.card=0;appRender();return}
 if(action==='jump-week'){let destination=add(S.day,+el.dataset.value);if(destination>today())return;S.day=destination;S.packet=null;S.card=0;appRender();return}
 if(action==='history'){S.history=el.dataset.value;appRender();return}
 if(action==='shift'){S.day=jump(S.history,S.day,+el.dataset.value);appRender();return}
 if(action==='open-day'){S.day=el.dataset.date;S.history='day';appRender();return}
 if(action==='open-month'){S.day=el.dataset.date;S.history='month';appRender();return}
 if(action==='edit-entry'){S.modal={type:'entry',id:el.dataset.id,day:el.dataset.date};S.entryStatus=null;modalRender();return}
 if(action==='entry-status'){S.entryStatus=el.dataset.value;$$('.status-option').forEach(x=>x.classList.toggle('on',x.dataset.value===S.entryStatus));return}
 if(action==='add-rule'){readRuleFields();S.ruleDraft.push({id:id(),period:'week',minutes:null,count:null});modalRender();return}
 if(action==='remove-rule'){readRuleFields();let n=+el.closest('[data-rule-index]').dataset.ruleIndex;S.ruleDraft.splice(n,1);modalRender();return}
 if(action==='period'){let o={type:'period',id:el.dataset.id,ruleId:el.dataset.rule,day:el.dataset.date,p:el.dataset.period};S.modal=o;S.entryStatus=OM.get(o.id+'|'+o.ruleId+'|'+period(o.p,o.day).start)?.status||null;modalRender();return}
 if(action==='delete-override'){let o=S.modal;await del('overrides',o.id+'|'+o.ruleId+'|'+period(o.p,o.day).start);close();await load();appRender();return}
 if(action==='remove-activity'){let a=S.activities.find(x=>x.id===el.dataset.id);if(!a||!confirm(`„${a.name}“ und alle Einträge endgültig löschen?`))return;await tx(['activities','entries','overrides'],'readwrite',t=>{t.objectStore('activities').delete(a.id);S.entries.filter(x=>x.activityId===a.id).forEach(x=>t.objectStore('entries').delete(x.id));S.overrides.filter(x=>x.activityId===a.id).forEach(x=>t.objectStore('overrides').delete(x.id))});close();await load();S.card=0;appRender();return}
 if(action==='move'){let sorted=[...S.activities],i=sorted.findIndex(a=>a.id===el.dataset.id),j=i+Number(el.dataset.value);if(j<0||j>=sorted.length)return;[sorted[i],sorted[j]]=[sorted[j],sorted[i]];await tx(['activities'],'readwrite',t=>sorted.forEach((a,k)=>t.objectStore('activities').put({...a,order:k})));await load();appRender();return}
 if(action==='skip-packets'){nextPacketPhase();return}
 if(action==='export'){await exportData();return}if(action==='import'){$('#importFile').click();return}if(action==='erase'){await eraseData();return}
 if(action==='dismiss-level'){$('#celebrateRoot').replaceChildren();if(S.packet)armTimer();return}
 }catch(err){errorAlert(err)}});
document.addEventListener('change',async e=>{let el=e.target;if(!el.dataset.setting)return;try{let k=el.dataset.setting,val=k==='sound'?el.checked:k==='packetTimeout'?Number(el.value):el.value;await setting(k,val)}catch(err){errorAlert(err)}});
document.addEventListener('input',e=>{if(e.target.dataset.setting==='packetTimeout')$('#timeoutLabel').textContent=e.target.value+' s'});
document.addEventListener('submit',async e=>{if(!['activityForm','entryForm','periodForm'].includes(e.target.id))return;e.preventDefault();try{if(e.target.id==='activityForm')await saveActivity(e.target);if(e.target.id==='entryForm')await saveEntry(e.target);if(e.target.id==='periodForm')await savePeriod(e.target)}catch(err){errorAlert(err)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&S.modal)close();if(S.page==='today'&&!S.modal&&!S.packet){if(e.key==='ArrowRight')rotateCards(1);if(e.key==='ArrowLeft')rotateCards(-1);if(e.key==='ArrowUp'&&openCards().length)playCard(openCards()[S.card].id,true).catch(errorAlert);if(e.key==='ArrowDown'&&openCards().length)playCard(openCards()[S.card].id,false).catch(errorAlert)}});
$('#importFile').addEventListener('change',async e=>{if(e.target.files[0])try{await importData(e.target.files[0])}catch(err){errorAlert(err)}e.target.value=''});
matchMedia('(prefers-color-scheme:dark)').addEventListener?.('change',()=>{if(S.theme==='system')theme()});
document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTimeout(timer);else if(S.packet)armTimer()});
init();
})();
